// ============================================================================
// REDACT & SHAPE  --  Tock reservation webhook -> privacy-minimal record
// This is the ONLY place Tock's raw payload is read. If a field name is ever
// wrong, fix it HERE (check api.exploretock.com reservation data model).
// Everything downstream (the sheet, the board) only ever sees 4 safe fields.
// ============================================================================

// --- CONFIG: must match the auth header you register with Tock ---
const AUTH_HEADER   = 'x-tock-token';
const SHARED_SECRET = 'CHANGE_ME_TO_A_LONG_RANDOM_STRING';

const input   = $input.first().json;
const headers = input.headers || {};
const token   = headers[AUTH_HEADER] || headers[AUTH_HEADER.toLowerCase()];

if (SHARED_SECRET && token !== SHARED_SECRET) {
  throw new Error('Unauthorized: missing or wrong ' + AUTH_HEADER + ' header');
}

// Tock may POST the reservation as the body, or nested under .reservation
const body = input.body || input;
const r    = body.reservation || body;

// Guest name shown in Tock = dinerPatron (fallback ownerPatron). We keep the
// first name + last INITIAL only. Full last name / email / phone never leave here.
const patron      = r.dinerPatron || r.ownerPatron || {};
const firstName   = (patron.firstName || '').trim();
const lastName    = (patron.lastName  || '').trim();
const lastInitial = lastName ? lastName.charAt(0).toUpperCase() : '';

// Tock dateTime = 24h "HH:MM" in the business timezone -> "h:mm AM/PM"
function to12h(hhmm) {
  if (!hhmm || String(hhmm).indexOf(':') === -1) return '';
  const p  = String(hhmm).split(':');
  let   h  = parseInt(p[0], 10);
  const m  = p[1];
  const ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12; if (h === 0) h = 12;
  return h + ':' + m + ' ' + ap;
}
const timeDisplay = to12h(r.dateTime);

// serviceDateTimestamp = ms since epoch (UTC) -- used for sorting / today-filter
const sortKey = r.serviceDateTimestamp ? Number(r.serviceDateTimestamp) : 0;

// Map Tock partyState + isCancelled -> board status
const state = String(r.partyState || '').toUpperCase();
let status;
if (r.isCancelled === true || state === 'CANCELLED' || state === 'NO_SHOW') {
  status = 'cancelled';
} else if (state === 'LEFT') {
  status = 'left';
} else if (['SEATED', 'PARTIALLY_SEATED', 'ARRIVED', 'PARTIALLY_ARRIVED'].indexOf(state) !== -1) {
  status = 'seated';
} else {
  status = 'upcoming';  // EXPECTED / default
}

// Stable dedup key so edits + cancels update the same row instead of duplicating
const reservationId = (r.id !== undefined && r.id !== null && r.id !== '')
  ? String(r.id)
  : String(r.confirmationCode || r.walkinId || '');

if (!reservationId) {
  throw new Error('No reservation id found in payload -- check the field mapping.');
}

// Output ONLY the scrubbed fields. These become the sheet columns.
return [{
  json: {
    reservationId: reservationId,
    sortKey:       sortKey,
    timeDisplay:   timeDisplay,
    firstName:     firstName,
    lastInitial:   lastInitial,
    status:        status,
    updatedAt:     new Date().toISOString()
  }
}];

// ============================================================================
// BUILD BOARD JSON  --  sheet rows -> the exact shape the display board wants:
// { updatedAt, reservations: [ { time, firstName, lastInitial, status } ] }
// ============================================================================

// --- CONFIG ---
const BUSINESS_TZ    = 'America/New_York'; // your shop timezone
const TODAY_ONLY     = true;               // hide anything not scheduled today
const KEEP_AFTER_MIN = 20;                 // keep a slot on the board this long after its time
const HIDE_STATUSES  = ['cancelled', 'left', 'no_show'];

const rows = $input.all().map(function (i) { return i.json; }).filter(Boolean);
const now  = Date.now();

function localDay(ms, tz) {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(new Date(ms));
}
function minsFromDisplay(t) {
  const m = String(t || '').match(/(\d+):(\d+)\s*([AP]M)?/i);
  if (!m) return null;
  let   h  = parseInt(m[1], 10);
  const mm = parseInt(m[2], 10);
  const ap = (m[3] || '').toUpperCase();
  if (ap === 'PM' && h < 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return h * 60 + mm;
}
function minsFromEpoch(ms, tz) {
  const s = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false
  }).format(new Date(ms));
  return minsFromDisplay(s);
}

const todayStr = localDay(now, BUSINESS_TZ);

const cleaned = rows.filter(function (row) {
  const status = String(row.status || 'upcoming').toLowerCase();
  if (HIDE_STATUSES.indexOf(status) !== -1) return false;

  const sortKey = Number(row.sortKey || 0);
  if (sortKey) {
    if (TODAY_ONLY && localDay(sortKey, BUSINESS_TZ) !== todayStr) return false;
    if ((now - sortKey) > KEEP_AFTER_MIN * 60000) return false;
  }
  return true;
});

cleaned.sort(function (a, b) {
  const ao = Number(a.sortKey) ? minsFromEpoch(Number(a.sortKey), BUSINESS_TZ) : minsFromDisplay(a.timeDisplay);
  const bo = Number(b.sortKey) ? minsFromEpoch(Number(b.sortKey), BUSINESS_TZ) : minsFromDisplay(b.timeDisplay);
  return (ao == null ? 9999 : ao) - (bo == null ? 9999 : bo);
});

const reservations = cleaned.map(function (row) {
  const s = String(row.status || 'upcoming').toLowerCase();
  return {
    time:        row.timeDisplay || '',
    firstName:   row.firstName || '',
    lastInitial: row.lastInitial || '',
    status:      s === 'seated' ? 'seated' : 'upcoming'
  };
});

return [{ json: { updatedAt: new Date().toISOString(), reservations: reservations } }];
